type Row = { name: string; amount: number };

interface SheetProps {
  columns: readonly SimpleColumn<Row>[];
  rows: readonly Row[];
  save: (transaction: Transaction) => void;
  onReady: (event: GridReadyEvent) => void;
}

export function Sheet({ columns, rows, save, onReady }: SheetProps) {
  return (
    <Sheetwrite
      columns={columns}
      defaultRows={rows}
      height={420}
      onGridChange={(event) => save(event.transaction)}
      onReady={onReady}
    />
  );
}

import {
  createGrid,
  initSheetwrite,
  type ChangeEvent,
  type ColumnarData,
  type Workbook,
} from "@sheetwrite/core";

export async function mountSheetwrite(
  host: HTMLElement,
  workbook: Workbook,
  data: ColumnarData,
  persistChange: (event: ChangeEvent) => void,
) {
  await initSheetwrite();
  const grid = createGrid(host, { workbook, data });
  const off = grid.on("change", persistChange);

  return () => {
    off();
    grid.destroy();
  };
}

